Lemma geo_1RB1LA_0LC1RD_1LA0RB_0LA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LC1RD_1LA0RB_0LA1RC) = lift (Cc (Pos.succ p)).
