(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1LA_0LC1RD_1LA0RB_0LA1RC : forall j, lift (cden [] [] j BB1_1RB1LA_0LC1RD_1LA0RB_0LA1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LC1RD_1LA0RB_0LA1RC = (StA, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_0LC1RD_1LA0RB_0LA1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
