(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LC1RD_1LA0RB_0LA1RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0LC1RD_1LA0RB_0LA1RC.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0LC1RD_1LA0RB_0LA1RC, cden, BE0_1RB1LA_0LC1RD_1LA0RB_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0LC1RD_1LA0RB_0LA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LA_0LC1RD_1LA0RB_0LA1RC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LC1RD_1LA0RB_0LA1RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LC1RD_1LA0RB_0LA1RC p (pow2 j)).
  - exists (6 * j + 11), (cden [] [] j BB1_1RB1LA_0LC1RD_1LA0RB_0LA1RC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LC1RD_1LA0RB_0LA1RC j)].
    rewrite (gso_1RB1LA_0LC1RD_1LA0RB_0LA1RC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC1RD_1LA0RB_0LA1RC B0_1RB1LA_0LC1RD_1LA0RB_0LA1RC BB1_1RB1LA_0LC1RD_1LA0RB_0LA1RC 6 11
             run_boot_1RB1LA_0LC1RD_1LA0RB_0LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 14), (cden [] [] j B1_1RB1LA_0LC1RD_1LA0RB_0LA1RC).
    split; [| exact (geo_1RB1LA_0LC1RD_1LA0RB_0LA1RC p j E)].
    rewrite (gxi_1RB1LA_0LC1RD_1LA0RB_0LA1RC j).
