(** ** Bootstrap *)

Lemma boot_1RB1LA_0LC1RD_1LA0RB_0LC0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
