(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_0LC1RD_1LA0RB_0LD1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_1RB1LA_0LC1RD_1LA0RB_0LD1RC.
