Lemma gei_1RB1LA_0LC1RD_1LA0RB_0LD1RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_1RB1LA_0LC1RD_1LA0RB_0LD1RC) = lift (Cc (Pos.succ p)).
Proof.
