(** ** The lap *)

Lemma lap_1RB1LA_0LC1RD_1LA0RB_0LD1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
