  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LC1RD_1LA0RB_0LD1RC B0_1RB1LA_0LC1RD_1LA0RB_0LD1RC B1_1RB1LA_0LC1RD_1LA0RB_0LD1RC 6 22 p j' [] []).
    + exact run_ovf_1RB1LA_0LC1RD_1LA0RB_0LD1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LC1RD_1LA0RB_0LD1RC p j' E).
    + exact (geo_1RB1LA_0LC1RD_1LA0RB_0LD1RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LC1RD_1LA0RB_0LD1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
