Lemma fireo_1RB1LA_0LC1RD_1LA0RB_0LD1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LC1RD_1LA0RB_0LD1RC = Some t ->
  forall p j, cview p = (S j, None) ->
