  - (* B0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LC1RD_1LA0RB_0LD1RC (StB, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LC1RD_1LA0RB_0LD1RC [SCycL 3 0; SWin 6; SCycR 3; SWin 3; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LC1RD_1LA0RB_0LD1RC [SCycL 3 0; SWin 5] (StB, S1) ltac:(vm_compute; reflexivity)
