  - destruct (lapi_1RB1LA_0LC1RD_1LA0RB_0RB1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LC1RD_1LA0RB_0RB1RC B0_1RB1LA_0LC1RD_1LA0RB_0RB1RC B1_1RB1LA_0LC1RD_1LA0RB_0RB1RC 6 22 p j' [] []).
    + exact run_ovf_1RB1LA_0LC1RD_1LA0RB_0RB1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LC1RD_1LA0RB_0RB1RC p j' E).
    + exact (geo_1RB1LA_0LC1RD_1LA0RB_0RB1RC p j' E).
    + lia.
