    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LC1RD_1LA0RD_0LC0RB
      with (l := [SRotL 1; SWin 3; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
