  - exists (4 * j + 9), (cden [] [] j BB1_1RB1LA_0LC1RD_1LA1LC_1RB0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LC1RD_1LA1LC_1RB0RB j)].
    rewrite (gso_1RB1LA_0LC1RD_1LA1LC_1RB0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC1RD_1LA1LC_1RB0RB B0_1RB1LA_0LC1RD_1LA1LC_1RB0RB BB1_1RB1LA_0LC1RD_1LA1LC_1RB0RB 4 9
             run_boot_1RB1LA_0LC1RD_1LA1LC_1RB0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 24), (cden [] [] j B1_1RB1LA_0LC1RD_1LA1LC_1RB0RB).
    split; [| exact (geo_1RB1LA_0LC1RD_1LA1LC_1RB0RB p j E)].
