(** ** The lap *)

Lemma lap_1RB1LA_0LC1RD_1LA1LC_1RB0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
