                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 7), (cden [] [] j BB1_1RB1LA_0LC1RD_1LC1LA_0LA0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LC1RD_1LC1LA_0LA0RB j)].
    rewrite (gso_1RB1LA_0LC1RD_1LC1LA_0LA0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC1RD_1LC1LA_0LA0RB B0_1RB1LA_0LC1RD_1LC1LA_0LA0RB BB1_1RB1LA_0LC1RD_1LC1LA_0LA0RB 4 7
             run_boot_1RB1LA_0LC1RD_1LC1LA_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_0LC1RD_1LC1LA_0LA0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 4), (cden [] [] j BM1_1RB1LA_0LC1RD_1LC1LA_0LA0RB).
    split; [| exact (gbo2_1RB1LA_0LC1RD_1LC1LA_0LA0RB j)].
    rewrite (gxi_1RB1LA_0LC1RD_1LC1LA_0LA0RB j).
    exact (srun_sound tm true true chm_1RB1LA_0LC1RD_1LC1LA_0LA0RB BM0_1RB1LA_0LC1RD_1LC1LA_0LA0RB BM1_1RB1LA_0LC1RD_1LC1LA_0LA0RB 4 4
             run_shift_1RB1LA_0LC1RD_1LC1LA_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB1LA_0LC1RD_1LC1LA_0LA0RB t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB1LA_0LC1RD_1LC1LA_0LA0RB xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB1LA_0LC1RD_1LC1LA_0LA0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LC1RD_1LC1LA_0LA0RB : forall t, ~ In t pins_1RB1LA_0LC1RD_1LC1LA_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LC1RD_1LC1LA_0LA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
