Lemma lapo_1RB1LA_0LC1RD_1LC1LA_0LC0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LC1RD_1LC1LA_0LC0RB p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB1LA_0LC1RD_1LC1LA_0LC0RB).
