    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LC1RD_1LC1LA_0LC0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_0LC1RD_1LC1LA_0LC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LC1RD_1LC1LA_0LC0RB = Some t ->
