Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_0LC1RD_1LC1LA_0LC0RB t p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB1LA_0LC1RD_1LC1LA_0LC0RB). split;
      [| exact (gbo_1RB1LA_0LC1RD_1LC1LA_0LC0RB j)].
