    exact (srun_sound tm true true chb_1RB1LA_0LC1RD_1LC1LA_0LC0RB B0_1RB1LA_0LC1RD_1LC1LA_0LC0RB BB1_1RB1LA_0LC1RD_1LC1LA_0LC0RB 4 9
             run_boot_1RB1LA_0LC1RD_1LC1LA_0LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
