    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LC1RD_1LC1LA_0LC0RB [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LC1RD_1LC1LA_0LC0RB : NeverQuasiHaltsTr tm_1RB1LA_0LC1RD_1LC1LA_0LC0RB.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LC1RD_1LC1LA_0LC0RB pins_1RB1LA_0LC1RD_1LC1LA_0LC0RB Cc 1).
