Definition che_1RB1LA_0LC1RD_1LC1LA_0LD0RB : list lstep := [SWin 2; SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 7; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1LA_0LC1RD_1LC1LA_0LD0RB : srun tm true true che_1RB1LA_0LC1RD_1LC1LA_0LD0RB BE0_1RB1LA_0LC1RD_1LC1LA_0LD0RB = Some (B1_1RB1LA_0LC1RD_1LC1LA_0LD0RB, 4, 19).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1LA_0LC1RD_1LC1LA_0LD0RB /\
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1LA_0LC1RD_1LC1LA_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LC1RD_1LC1LA_0LD0RB, cden, Z0_1RB1LA_0LC1RD_1LC1LA_0LD0RB, Z1_1RB1LA_0LC1RD_1LC1LA_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S1;S0]) with (([S1]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_1RB1LA_0LC1RD_1LC1LA_0LD0RB /\
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_1RB1LA_0LC1RD_1LC1LA_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LC1RD_1LC1LA_0LD0RB, cden, P0_1RB1LA_0LC1RD_1LC1LA_0LD0RB, P1_1RB1LA_0LC1RD_1LC1LA_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S1;S0]) with (([S1]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_0LC1RD_1LC1LA_0LD0RB p q0 E) as (HA & HB).
    exists (0 * 0 + 10), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1LA_0LC1RD_1LC1LA_0LD0RB).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB1LA_0LC1RD_1LC1LA_0LD0RB Z0_1RB1LA_0LC1RD_1LC1LA_0LD0RB Z1_1RB1LA_0LC1RD_1LC1LA_0LD0RB 0 10
             run_z_1RB1LA_0LC1RD_1LC1LA_0LD0RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB1LA_0LC1RD_1LC1LA_0LD0RB p j' q0 E) as (HA & HB).
    exists (4 * j' + 14), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j' P1_1RB1LA_0LC1RD_1LC1LA_0LD0RB).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB1LA_0LC1RD_1LC1LA_0LD0RB P0_1RB1LA_0LC1RD_1LC1LA_0LD0RB P1_1RB1LA_0LC1RD_1LC1LA_0LD0RB 4 14
             run_p_1RB1LA_0LC1RD_1LC1LA_0LD0RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0LC1RD_1LC1LA_0LD0RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB1LA_0LC1RD_1LC1LA_0LD0RB, cden, B0_1RB1LA_0LC1RD_1LC1LA_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LC1RD_1LC1LA_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0LC1RD_1LC1LA_0LD0RB
             = (StC, (rep [S1;S0] (S j) ++ [S1;S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, B1_1RB1LA_0LC1RD_1LC1LA_0LD0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB1LA_0LC1RD_1LC1LA_0LD0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1LA_0LC1RD_1LC1LA_0LD0RB. reflexivity.
Qed.

Lemma gsn_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1LA_0LC1RD_1LC1LA_0LD0RB.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB1LA_0LC1RD_1LC1LA_0LD0RB, cden, AI0_1RB1LA_0LC1RD_1LC1LA_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_0LC1RD_1LC1LA_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_0LC1RD_1LC1LA_0LD0RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_0LC1RD_1LC1LA_0LD0RB, cden, AI1_1RB1LA_0LC1RD_1LC1LA_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
