    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_0LC1RD_1RB1RD_0LA0RC Z0_1RB1LA_0LC1RD_1RB1RD_0LA0RC Z1_1RB1LA_0LC1RD_1RB1RD_0LA0RC 0 4
               run_z_1RB1LA_0LC1RD_1RB1RD_0LA0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_0LC1RD_1RB1RD_0LA0RC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_0LC1RD_1RB1RD_0LA0RC P0_1RB1LA_0LC1RD_1RB1RD_0LA0RC P1_1RB1LA_0LC1RD_1RB1RD_0LA0RC 4 8
               run_p_1RB1LA_0LC1RD_1RB1RD_0LA0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
