  - destruct (lapi_1RB1LA_0LC1RD_1RB1RD_0LA0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LC1RD_1RB1RD_0LA0RC B0_1RB1LA_0LC1RD_1RB1RD_0LA0RC B1_1RB1LA_0LC1RD_1RB1RD_0LA0RC 4 9 p j' [] []).
    + exact run_ovf_1RB1LA_0LC1RD_1RB1RD_0LA0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LC1RD_1RB1RD_0LA0RC p j' E).
    + exact (geo_1RB1LA_0LC1RD_1RB1RD_0LA0RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LC1RD_1RB1RD_0LA0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LC1RD_1RB1RD_0LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LC1RD_1RB1RD_0LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LC1RD_1RB1RD_0LA0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LC1RD_1RB1RD_0LA0RC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LC1RD_1RB1RD_0LA0RC : forall t, ~ In t pins_1RB1LA_0LC1RD_1RB1RD_0LA0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
