Lemma gz_1RB1LA_0LC1RD_1RD1LA_0LC0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1LA_0LC1RD_1RD1LA_0LC0RB /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1LA_0LC1RD_1RD1LA_0LC0RB = Cc (Pos.succ p).
