Lemma gsi_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
