Lemma geo_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0RC0RD_1LC0RA_0RB0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0RC0RD_1LC0RA_0RB0LC
