Lemma gsn_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
Proof.
