  unfold Cin_1RB1LA_0RC0RD_1LC0RA_0RB0LC, cden, AI0_1RB1LA_0RC0RD_1LC0RA_0RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ []) [] i AI1_1RB1LA_0RC0RD_1LC0RA_0RB0LC) = lift (Cin (Pos.succ v)).
Proof.
