    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB1LA_0RC0RD_1LC0RA_0RB0LC. rewrite epow2_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
