(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0RC0RD_1LC0RA_0RB0LC p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB1LA_0RC0RD_1LC0RA_0RB0LC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0RC0RD_1LC0RA_0RB0LC j)].
    rewrite (gso_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0RC0RD_1LC0RA_0RB0LC B0_1RB1LA_0RC0RD_1LC0RA_0RB0LC BB1_1RB1LA_0RC0RD_1LC0RA_0RB0LC 4 6
             run_boot_1RB1LA_0RC0RD_1LC0RA_0RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_1RB1LA_0RC0RD_1LC0RA_0RB0LC).
    split; [| exact (geo_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j E)].
    rewrite (gxi_1RB1LA_0RC0RD_1LC0RA_0RB0LC j).
    exact (srun_sound tm true true che_1RB1LA_0RC0RD_1LC0RA_0RB0LC BE0_1RB1LA_0RC0RD_1LC0RA_0RB0LC B1_1RB1LA_0RC0RD_1LC0RA_0RB0LC 4 10
             run_exit_1RB1LA_0RC0RD_1LC0RA_0RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
