(** ** The lap *)

Lemma lap_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
