  - destruct (lapi_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0RC0RD_1LC0RA_0RB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0RC0RD_1LC0RA_0RB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0RC0RD_1LC0RA_0RB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_0RC0RD_1LC0RA_0RB0LC t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB1LA_0RC0RD_1LC0RA_0RB0LC). split;
      [| exact (gbo_1RB1LA_0RC0RD_1LC0RA_0RB0LC j)].
    rewrite (gso_1RB1LA_0RC0RD_1LC0RA_0RB0LC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0RC0RD_1LC0RA_0RB0LC B0_1RB1LA_0RC0RD_1LC0RA_0RB0LC BB1_1RB1LA_0RC0RD_1LC0RA_0RB0LC 4 6
             run_boot_1RB1LA_0RC0RD_1LC0RA_0RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_0RC0RD_1LC0RA_0RB0LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_0RC0RD_1LC0RA_0RB0LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0RC0RD_1LC0RA_0RB0LC : forall t, ~ In t pins_1RB1LA_0RC0RD_1LC0RA_0RB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0RC0RD_1LC0RA_0RB0LC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0RC0RD_1LC0RA_0RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0RC0RD_1LC0RA_0RB0LC (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0RC0RD_1LC0RA_0RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LA_0RC0RD_1LC0RA_0RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB1LA_0RC0RD_1LC0RA_0RB0LC : NeverQuasiHaltsTr tmm_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
Proof.
  apply (glue_neverqhtr tmm_1RB1LA_0RC0RD_1LC0RA_0RB0LC pins_1RB1LA_0RC0RD_1LC0RA_0RB0LC Cc 1).
  - exact boot_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
  - intros p _. apply lap_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
  - intros t Ht p _. apply fire_1RB1LA_0RC0RD_1LC0RA_0RB0LC. exact Ht.
Qed.

Theorem nqhtr_1RB1LA_0RC0RD_1LC0RA_0RB0LC : NeverQuasiHaltsTr tm_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
Proof. apply (neverqhtr_mirror tm_1RB1LA_0RC0RD_1LC0RA_0RB0LC). rewrite mirror_ok_1RB1LA_0RC0RD_1LC0RA_0RB0LC. exact nqhtrm_1RB1LA_0RC0RD_1LC0RA_0RB0LC. Qed.

Theorem nonhalt_1RB1LA_0RC0RD_1LC0RA_0RB0LC : NonHalt tm_1RB1LA_0RC0RD_1LC0RA_0RB0LC.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1LA_0RC0RD_1LC0RA_0RB0LC. Qed.

