Lemma lapi_1RB1LA_0RC1LB_1LA1RD_1RC0LB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB1LA_0RC1LB_1LA1RD_1RC0LB p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LA_0RC1LB_1LA1RD_1RC0LB A0_1RB1LA_0RC1LB_1LA1RD_1RC0LB A1_1RB1LA_0RC1LB_1LA1RD_1RC0LB 4 4
             run_int_1RB1LA_0RC1LB_1LA1RD_1RC0LB (Jp q0 ++ [S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LA_0RC1LB_1LA1RD_1RC0LB p j q0 E).
Qed.

Lemma gso_1RB1LA_0RC1LB_1LA1RD_1RC0LB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0RC1LB_1LA1RD_1RC0LB.
