Lemma gen_1RB1LA_0RC1LB_1LA1RD_1RC0LB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ []) [] i AI1_1RB1LA_0RC1LB_1LA1RD_1RC0LB) = lift (Cin (Pos.succ v)).
