  split; [lia|]. split; [| exact (gen_1RB1LA_0RC1LB_1LA1RD_1RC0LB v i q0 E)].
  rewrite (gsn_1RB1LA_0RC1LB_1LA1RD_1RC0LB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0RC1LB_1LA1RD_1RC0LB AI0_1RB1LA_0RC1LB_1LA1RD_1RC0LB AI1_1RB1LA_0RC1LB_1LA1RD_1RC0LB 4 4
           run_inner_1RB1LA_0RC1LB_1LA1RD_1RC0LB (Jp q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
