    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  4*j+8 steps
      overflow  (cview p = (S j, None)):   boot 4*j+8, then the inner counter's own laps to the
                                           all-ones fill, then exit 4*j+13

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter JpCounter LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_1RB1LA_0RC1LB_1RD0LB_1LA1RC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LA_0RC1LB_1RD0LB_1LA1RC.

(** 1RB1LA_0RC1LB_1RD0LB_1LA1RC *)
(** 1RB1LA_0RC1LB_1RD0LB_1LA1RC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LA_0RC1LB_1RD0LB_1LA1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DR StC end.

(** Its mirror 1LB1RA_0LC1RB_1LD0RB_1RA1LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LA_0RC1LB_1RD0LB_1LA1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_0RC1LB_1RD0LB_1LA1RC : list Instr := [].
Definition tmw_1RB1LA_0RC1LB_1RD0LB_1LA1RC : TM := tm_wrap_trs tmm_1RB1LA_0RC1LB_1RD0LB_1LA1RC pins_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
Local Notation tm := tmw_1RB1LA_0RC1LB_1RD0LB_1LA1RC.

Lemma mirror_ok_1RB1LA_0RC1LB_1RD0LB_1LA1RC : mirror_tm tm_1RB1LA_0RC1LB_1RD0LB_1LA1RC = tmm_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LA_0RC1LB_1RD0LB_1LA1RC (p : positive) : cconf := (StC, (Jp p ++ [S1;S0], S0, [])).
Local Notation Cc := Cc_1RB1LA_0RC1LB_1RD0LB_1LA1RC.

(** ** The certificate *)

Definition A0_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB1LA_0RC1LB_1RD0LB_1LA1RC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_int_1RB1LA_0RC1LB_1RD0LB_1LA1RC : srun tm false true chi_1RB1LA_0RC1LB_1RD0LB_1LA1RC A0_1RB1LA_0RC1LB_1RD0LB_1LA1RC = Some (A1_1RB1LA_0RC1LB_1RD0LB_1LA1RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StC *)
Definition Cin_1RB1LA_0RC1LB_1RD0LB_1LA1RC (v : positive) : cconf := (StC, (Jp v ++ [], S0, [])).
Local Notation Cin := Cin_1RB1LA_0RC1LB_1RD0LB_1LA1RC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB1LA_0RC1LB_1RD0LB_1LA1RC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_inner_1RB1LA_0RC1LB_1RD0LB_1LA1RC : srun tm false true chn_1RB1LA_0RC1LB_1RD0LB_1LA1RC AI0_1RB1LA_0RC1LB_1RD0LB_1LA1RC = Some (AI1_1RB1LA_0RC1LB_1RD0LB_1LA1RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0;S0]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB1LA_0RC1LB_1RD0LB_1LA1RC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWinR 4].

Lemma run_boot_1RB1LA_0RC1LB_1RD0LB_1LA1RC : srun tm true true chb_1RB1LA_0RC1LB_1RD0LB_1LA1RC B0_1RB1LA_0RC1LB_1RD0LB_1LA1RC = Some (BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LA_0RC1LB_1RD0LB_1LA1RC : list lstep := [SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWinR 7; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1LA_0RC1LB_1RD0LB_1LA1RC : srun tm true true che_1RB1LA_0RC1LB_1RD0LB_1LA1RC BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC = Some (B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC, 4, 13).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_0RC1LB_1RD0LB_1LA1RC, cden, A0_1RB1LA_0RC1LB_1RD0LB_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S1;S0]) [] j A1_1RB1LA_0RC1LB_1RD0LB_1LA1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_0RC1LB_1RD0LB_1LA1RC, cden, A1_1RB1LA_0RC1LB_1RD0LB_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Jp q0 ++ [S1;S0]) [] j A1_1RB1LA_0RC1LB_1RD0LB_1LA1RC).
  split; [lia|]. split; [| exact (gei_1RB1LA_0RC1LB_1RD0LB_1LA1RC p j q0 E)].
  rewrite (gsi_1RB1LA_0RC1LB_1RD0LB_1LA1RC p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_0RC1LB_1RD0LB_1LA1RC A0_1RB1LA_0RC1LB_1RD0LB_1LA1RC A1_1RB1LA_0RC1LB_1RD0LB_1LA1RC 4 8
           run_int_1RB1LA_0RC1LB_1RD0LB_1LA1RC (Jp q0 ++ [S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB1LA_0RC1LB_1RD0LB_1LA1RC, cden, B0_1RB1LA_0RC1LB_1RD0LB_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC
             = (StC, (rep [S1;S1] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_0RC1LB_1RD0LB_1LA1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1LA_0RC1LB_1RD0LB_1LA1RC. reflexivity.
Qed.

Lemma gsn_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ []) [] i AI0_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_1RB1LA_0RC1LB_1RD0LB_1LA1RC, cden, AI0_1RB1LA_0RC1LB_1RD0LB_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ []) [] i AI1_1RB1LA_0RC1LB_1RD0LB_1LA1RC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_0RC1LB_1RD0LB_1LA1RC, cden, AI1_1RB1LA_0RC1LB_1RD0LB_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Jp q0 ++ []) [] i AI1_1RB1LA_0RC1LB_1RD0LB_1LA1RC).
  split; [lia|]. split; [| exact (gen_1RB1LA_0RC1LB_1RD0LB_1LA1RC v i q0 E)].
  rewrite (gsn_1RB1LA_0RC1LB_1RD0LB_1LA1RC v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0RC1LB_1RD0LB_1LA1RC AI0_1RB1LA_0RC1LB_1RD0LB_1LA1RC AI1_1RB1LA_0RC1LB_1RD0LB_1LA1RC 4 8
           run_inner_1RB1LA_0RC1LB_1RD0LB_1LA1RC (Jp q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 2/1
    trailing blanks. *)
Lemma gbo_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall j, lift (cden [] [] j BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC = (StC, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB1LA_0RC1LB_1RD0LB_1LA1RC. rewrite epow2_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0RC1LB_1RD0LB_1LA1RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0RC1LB_1RD0LB_1LA1RC, cden, BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LA_0RC1LB_1RD0LB_1LA1RC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0RC1LB_1RD0LB_1LA1RC p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0RC1LB_1RD0LB_1LA1RC j)].
    rewrite (gso_1RB1LA_0RC1LB_1RD0LB_1LA1RC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0RC1LB_1RD0LB_1LA1RC B0_1RB1LA_0RC1LB_1RD0LB_1LA1RC BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC 4 8
             run_boot_1RB1LA_0RC1LB_1RD0LB_1LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 13), (cden [] [] j B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC).
    split; [| exact (geo_1RB1LA_0RC1LB_1RD0LB_1LA1RC p j E)].
    rewrite (gxi_1RB1LA_0RC1LB_1RD0LB_1LA1RC j).
    exact (srun_sound tm true true che_1RB1LA_0RC1LB_1RD0LB_1LA1RC BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC B1_1RB1LA_0RC1LB_1RD0LB_1LA1RC 4 13
             run_exit_1RB1LA_0RC1LB_1RD0LB_1LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LA_0RC1LB_1RD0LB_1LA1RC : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1LA_0RC1LB_1RD0LB_1LA1RC q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC). split;
      [| exact (gbo_1RB1LA_0RC1LB_1RD0LB_1LA1RC j)].
    rewrite (gso_1RB1LA_0RC1LB_1RD0LB_1LA1RC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0RC1LB_1RD0LB_1LA1RC B0_1RB1LA_0RC1LB_1RD0LB_1LA1RC BB1_1RB1LA_0RC1LB_1RD0LB_1LA1RC 4 8
             run_boot_1RB1LA_0RC1LB_1RD0LB_1LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_0RC1LB_1RD0LB_1LA1RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_0RC1LB_1RD0LB_1LA1RC j)].
