    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_0RC1RC_0LD0RB_0LA0RB. rewrite epow2_1RB1LA_0RC1RC_0LD0RB_0LA0RB.
    first [ rewrite <- app_assoc; reflexivity
