(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_0RC1RC_0LD0RB_0LA1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LA_0RC1RC_0LD0RB_0LA1RD.
