Lemma fireo_1RB1LA_0RC1RC_0LD0RB_1LA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0RC1RC_0LD0RB_1LA1LD = Some t ->
