Lemma geo_1RB1LA_0RC1RC_0LD0RB_1RC1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0RC1RC_0LD0RB_1RC1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0RC1RC_0LD0RB_1RC1LA
             = (StC, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
