(** ** The lap *)

Lemma lap_1RB1LA_0RC1RC_0LD0RB_1RC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
