  - destruct (lapi_1RB1LA_0RC1RC_0LD0RB_1RC1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0RC1RC_0LD0RB_1RC1LA B0_1RB1LA_0RC1RC_0LD0RB_1RC1LA B1_1RB1LA_0RC1RC_0LD0RB_1RC1LA 4 9 p j' [] []).
    + exact run_ovf_1RB1LA_0RC1RC_0LD0RB_1RC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0RC1RC_0LD0RB_1RC1LA p j' E).
    + exact (geo_1RB1LA_0RC1RC_0LD0RB_1RC1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0RC1RC_0LD0RB_1RC1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
