  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0RC1RC_0LD0RB_1RC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0RC1RC_0LD0RB_1RC1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0RC1RC_0LD0RB_1RC1LA : forall t, ~ In t pins_1RB1LA_0RC1RC_0LD0RB_1RC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
