(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0RC1RC_0LD1RD_0LA0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1LA_0RC1RC_0LD1RD_0LA0RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 6), (cden [] [] j BB1_1RB1LA_0RC1RC_0LD1RD_0LA0RB).
      split; [lia|]. split; [| exact (gbo_1RB1LA_0RC1RC_0LD1RD_0LA0RB j)].
      rewrite (gso_1RB1LA_0RC1RC_0LD1RD_0LA0RB p j E).
      exact (srun_sound tm true true chb_1RB1LA_0RC1RC_0LD1RD_0LA0RB B0_1RB1LA_0RC1RC_0LD1RD_0LA0RB BB1_1RB1LA_0RC1RC_0LD1RD_0LA0RB 6 6
               run_boot_1RB1LA_0RC1RC_0LD1RD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_0RC1RC_0LD1RD_0LA0RB p (pow2 j) (pow2 j));
