      exact (srun_sound tm true true chm_1RB1LA_0RC1RC_0LD1RD_0LA0RB BM0_1RB1LA_0RC1RC_0LD1RD_0LA0RB BM1_1RB1LA_0RC1RC_0LD1RD_0LA0RB 6 14
               run_shift_1RB1LA_0RC1RC_0LD1RD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
