  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0RC1RC_0LD1RD_0LA0RB (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0RC1RC_0LD1RD_0LA0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
