(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0RC1RD_1LD0LD_0LA0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1LA_0RC1RD_1LD0LD_0LA0RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (4 * j + 11), (cden [] [] j BB1_1RB1LA_0RC1RD_1LD0LD_0LA0RB).
      split; [lia|]. split; [| exact (gbo_1RB1LA_0RC1RD_1LD0LD_0LA0RB j)].
      rewrite (gso_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j E).
      exact (srun_sound tm true true chb_1RB1LA_0RC1RD_1LD0LD_0LA0RB B0_1RB1LA_0RC1RD_1LD0LD_0LA0RB BB1_1RB1LA_0RC1RD_1LD0LD_0LA0RB 4 11
               run_boot_1RB1LA_0RC1RD_1LD0LD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_0RC1RD_1LD0LD_0LA0RB p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (4 * j + 4), (cden [] [] j BM1_1RB1LA_0RC1RD_1LD0LD_0LA0RB).
      split; [| exact (gbo2_1RB1LA_0RC1RD_1LD0LD_0LA0RB j)].
      rewrite (gxi_1RB1LA_0RC1RD_1LD0LD_0LA0RB j).
      exact (srun_sound tm true true chm_1RB1LA_0RC1RD_1LD0LD_0LA0RB BM0_1RB1LA_0RC1RD_1LD0LD_0LA0RB BM1_1RB1LA_0RC1RD_1LD0LD_0LA0RB 4 4
               run_shift_1RB1LA_0RC1RD_1LD0LD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (4 * j + 13), (cden [] [] j B1_1RB1LA_0RC1RD_1LD0LD_0LA0RB).
    split; [| exact (geo_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j E)].
    rewrite (gxi2_1RB1LA_0RC1RD_1LD0LD_0LA0RB j).
    exact (srun_sound tm true true che_1RB1LA_0RC1RD_1LD0LD_0LA0RB BE0_1RB1LA_0RC1RD_1LD0LD_0LA0RB B1_1RB1LA_0RC1RD_1LD0LD_0LA0RB 4 13
             run_exit_1RB1LA_0RC1RD_1LD0LD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0RC1RD_1LD0LD_0LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0RC1RD_1LD0LD_0LA0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 16.
  assert (H : match csteps tm 16 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 16 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0RC1RD_1LD0LD_0LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0RC1RD_1LD0LD_0LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LA_0RC1RD_1LD0LD_0LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LA_0RC1RD_1LD0LD_0LA0RB = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LA_0RC1RD_1LD0LD_0LA0RB p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0RC1RD_1LD0LD_0LA0RB : forall t, ~ In t pins_1RB1LA_0RC1RD_1LD0LD_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0RC1RD_1LD0LD_0LA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0RC1RD_1LD0LD_0LA0RB [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0RC1RD_1LD0LD_0LA0RB [SWinR 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0RC1RD_1LD0LD_0LA0RB [SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0RC1RD_1LD0LD_0LA0RB [SWinR 4; SCycL 2 0; SWin 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0RC1RD_1LD0LD_0LA0RB [SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
